  // pricing (more)
  "pricing.save": ["{n}% tejaysiz", "Экономия {n}%", "Save {n}%"],
  "pricing.current": ["Hozirgi tarif", "Текущий тариф", "Current plan"],
  "pricing.freeF1": ["Boshlangʻich darslar va 1–3 kunlar", "Вводные уроки и дни 1–3", "Orientation and days 1–3"],
  "pricing.freeF2": ["Barcha 50 ta video dars", "Все 50 видеоуроков", "All 50 video lessons"],
  "pricing.freeF3": ["AI oʻqituvchi: kuniga 3 ta tekshiruv", "AI-учитель: 3 проверки в день", "AI teacher: 3 checks a day"],
  "pricing.signinToBuy": ["Sotib olish uchun avval kiring", "Чтобы купить, сначала войдите", "Sign in first to buy"],
  "pricing.staff": ["Xodim hisobida hamma narsa ochiq.", "У сотрудников всё уже открыто.", "Staff accounts already have everything."],
  "pricing.stack": ["Yana sotib olsangiz, kunlar ustiga qoʻshiladi.", "Повторная покупка добавляет дни к текущему сроку.", "Buying again adds the days on top of what you have."],
  "pricing.opening": ["Toʻlov sahifasi ochilmoqda…", "Открываем страницу оплаты…", "Opening the checkout…"],
  "pricing.support": ["Admin bilan bogʻlanish", "Написать администратору", "Message the admin"],
  "pricing.faq": ["Savollar", "Вопросы", "Questions"],
  "pricing.q1": ["Bu obunami?", "Это подписка?", "Is this a subscription?"],
  "pricing.a1": ["Yoʻq. 1 yoki 3 oy uchun bir marta toʻlaysiz. Hech narsa avtomatik yechilmaydi; xohlagan paytda yana sotib olasiz va kunlar qoʻshiladi.", "Нет. Вы платите один раз за 1 или 3 месяца. Автосписаний нет; можно купить снова в любое время, и дни сложатся.", "No. You pay once for 1 or 3 months. Nothing renews automatically; buy again any time and the days add up."],
  "pricing.q2": ["Tarif qachon ochiladi?", "Когда откроется тариф?", "When does my plan open?"],
  "pricing.a2": ["Odatda toʻlovdan keyin bir daqiqa ichida. Ochilmasa, sahifani yangilang yoki hisob raqamingizni adminga yuboring.", "Обычно в течение минуты после оплаты. Если нет — обновите страницу или отправьте администратору ID аккаунта.", "Usually within a minute of paying. If it doesn't, refresh this page or send the admin your account ID."],
  "pricing.q3": ["Mustaqil va Pro farqi nima?", "Чем отличается Самостоятельный от Pro?", "What's the difference between Self-study and Pro?"],
  "pricing.a3": ["Mustaqil: butun ilova — barcha darslar, grammatika, takrorlash, AI oʻqituvchi va oyiga 30 daqiqa ovozli oʻqituvchi. Pro bunga jonli oʻqituvchini qoʻshadi: haftasiga 3 ta dars, DOT tekshiruvi mashqi, 300 daqiqa va Telegram chat.", "Самостоятельный — всё приложение: все уроки, грамматика, повторение, AI-учитель и 30 минут голосового учителя в месяц. Pro добавляет живого учителя: 3 урока в неделю, тренировку проверки DOT, 300 минут и чат в Telegram.", "Self-study is the whole app: every lesson, grammar, review, the AI teacher and 30 voice-teacher minutes a month. Pro adds a real teacher: live classes 3 times a week, mock DOT inspections, 300 minutes and a Telegram chat."],

