  // practice: listening in the truck, conversation practice, games
  "nav.practice": ["Mashq", "Практика", "Practice"],
  "practice.title": ["Mashq", "Практика", "Practice"],
  "practice.sub": ["Har kuni bir oz: yoʻlda tinglang, real vaziyatlarda gaplashing, raqamlarni eshitib tushunishni oʻrganing.", "Понемногу каждый день: слушайте в дороге, разговаривайте в реальных ситуациях, учитесь понимать числа на слух.", "A little every day: listen on the road, talk through real situations, learn to catch numbers by ear."],
  "practice.games": ["Oʻyin-mashqlar", "Игры-упражнения", "Practice games"],
  "practice.reviewLater": ["Hozircha takrorlash yoʻq. Soʻzlaringiz keyinroq qaytadi.", "Сейчас повторять нечего. Слова вернутся позже.", "Nothing due right now. Your words will come back later."],
  "practice.from": ["Qaysi soʻzlar bilan", "Какие слова", "Practice with"],
  "practice.mine": ["Mening soʻzlarim (takrorlash, {n} ta)", "Мои слова (повтор, {n})", "My words (review, {n})"],
  "listen.title": ["Yoʻlda tinglash", "Слушать в дороге", "Listen in the truck"],
  "listen.sub": ["Ekranga qaramasdan: inglizcha ibora, uning maʼnosi, siz takrorlaysiz, keyin yana inglizcha.", "Не глядя на экран: фраза по-английски, её значение, вы повторяете, и ещё раз по-английски.", "No need to look at the screen: the English phrase, its meaning, you repeat it, then the English again."],
  "listen.safety": ["Haydashdan oldin sozlab qoʻying. Yoʻlda ekranga qaramang va unga tegmang: quloqchin yoki rul tugmalaridan foydalaning.", "Настройте до начала поездки. В дороге не смотрите на экран и не трогайте его: пользуйтесь кнопками наушников или руля.", "Set it up before you drive. While driving, don't look at or touch the screen: use your headphone or steering-wheel buttons."],
  "listen.you": ["Siz takrorlang", "Ваша очередь", "Your turn"],
  "listen.play": ["Tinglash", "Слушать", "Play"],
  "listen.pause": ["Pauza", "Пауза", "Pause"],
  "listen.optTr": ["Tarjimasini ham aytish", "Произносить перевод", "Say the translation too"],
  "listen.optLoop": ["Oxiriga yetganda boshidan boshlash", "По кругу", "Start again at the end"],
  "listen.optShuffle": ["Aralash tartibda", "Вперемешку", "Shuffle"],
