let current = (() => {
  try { const s = localStorage.getItem(KEY); if (LANGS.includes(s)) return s; } catch { /* ignore */ }
  const n = (navigator.language || "").toLowerCase();
  return n.startsWith("ru") ? "ru" : n.startsWith("en") ? "en" : "uz";
})();
document.documentElement.lang = current;

export function lang() { return current; }
/** The language course translations are shown in (English UI still gets the Uzbek translations). */
export function trLang() { return current === "ru" ? "ru" : "uz"; }
export function setLang(l) {
  if (!LANGS.includes(l)) return;
  current = l;
  try { localStorage.setItem(KEY, l); } catch { /* ignore */ }
  document.documentElement.lang = l;
}
export function t(k, vars) {
  const row = D[k];
  let s = row ? row[LANGS.indexOf(current)] || row[0] : k;
  if (vars) s = s.replace(/\{(\w+)\}/g, (m, v) => (vars[v] != null ? vars[v] : m));
  return s;
}
/** Picks the right language from a content object {en, uz, ru}. */
export function pick(o, l = trLang()) {
  if (!o) return "";
  if (typeof o === "string") return o;
  return o[l] || o.uz || o.en || "";
}
const UZ_MONTHS = ["yanvar", "fevral", "mart", "aprel", "may", "iyun", "iyul", "avgust", "sentabr", "oktabr", "noyabr", "dekabr"];
export function fmtDate(ms) {
  if (!ms) return "";
  const d = new Date(ms);
  // browsers have no proper Uzbek month names ("2026 M11 15"), so Uzbek is formatted by hand: "2026-yil 15-noyabr"
  if (current === "uz") return `${d.getFullYear()}-yil ${d.getDate()}-${UZ_MONTHS[d.getMonth()]}`;
  try { return d.toLocaleDateString(current === "ru" ? "ru-RU" : "en-US", { day: "numeric", month: "long", year: "numeric" }); } catch { return d.toDateString(); }
}
export function fmtWhen(ms) {
  const d = ms - Date.now();
  if (d <= 60 * 1000) return { uz: "hozir", ru: "сейчас", en: "now" }[current];
  const h = Math.round(d / 3600000);
  if (h < 24) return { uz: `${Math.max(1, h)} soatdan keyin`, ru: `через ${Math.max(1, h)} ч`, en: `in ${Math.max(1, h)} h` }[current];
  const days = Math.round(d / 86400000);
  return { uz: `${days} kundan keyin`, ru: `через ${days} дн.`, en: `in ${days} days` }[current];
}
